// Reference solution
function ifMatch(header, current) {
  if (header === undefined) return 'ok';
  const tags = header.split(',').map((s) => s.trim());
  if (tags.includes('*')) return 'ok';
  return tags.some((t) => !t.startsWith('W/') && t === current) ? 'ok' : 'precondition-failed';
}

