/** UPDATE … WHERE id = $1 AND version = $2, simulated */
function guardedUpdate(rows, id, expectedVersion, patch) {
  // Write your solution here
  const r = rows.find((x) => x.id === id);
  Object.assign(r, patch);
  return { updated: 1, rows };
}

